                ctx.restore();
            }

            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);
        }

        ctx.restore(); 

        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { VFXStateManager } from "./vfx/state";

const GRAVITY = 1800; // Gravity for particles

export class VFXSystem {
    // Encapsulated State
    public state: VFXStateManager = new VFXStateManager();

    // Ambient Spawn State
    private ambientTimer: number = 0;

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        // Update Particles
        // PERF: Iterate backwards to allow Swap-Pop removal
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                // PERF: Swap-and-Pop O(1) removal
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- PHYSICS UPDATE ---
            // Types affected by gravity and floor collisions
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE';

            if (isPhysical) {
                // Get ground height at particle position
                let groundH = 0;
                if (getTerrainHeight) {
                    groundH = getTerrainHeight(p.x, p.y);
                }

                // RESTING CHECK (The Anti-Jitter Fix)
                // If on ground (at terrain height) and barely moving
                const distToGround = p.z - groundH;
                const isResting = distToGround <= 0.5 && Math.abs(p.vz) < 50 && Math.abs(p.vx) < 10 && Math.abs(p.vy) < 10;

                if (isResting) {
                    p.z = groundH; // Snap to terrain top
                    p.vz = 0;
                    p.vx = 0;
                    p.vy = 0;
                    p.vRotation = 0;
                    // Skip integration, just render static
                } else {
                    // Apply Gravity
                    p.vz -= GRAVITY * dt;

                    // Integrate Position
                    p.x += p.vx * dt;
                    p.y += p.vy * dt;
                    p.z += p.vz * dt;
                    p.rotation += p.vRotation * dt;

                    // Ground Collision
                    if (p.z < groundH) {
                        p.z = groundH;
                        // Bounce Logic
                        if (Math.abs(p.vz) > 100) {
                            // High Energy: Bounce
                            p.vz = -p.vz * 0.5; 
                            p.vx *= 0.6; // Friction on bounce
                            p.vy *= 0.6;
                            p.vRotation *= 0.5;
                        } else {
                            // Low Energy: Slide
                            p.vz = 0;
                            // Heavy Ground Friction
                            p.vx *= 0.1; 
                            p.vy *= 0.1;
                            p.vRotation *= 0.1;
                        }
                    }
                }
            } else {
                // Non-Physical Particles (Smoke, Sparks, etc.)
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; // Drag
                } else if (p.type === 'GLOW') {
                    // Ambient particles float/wobble
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                // Simple Splice OK here as count is low
                this.state.decals.splice(i, 1);
            }
        }

        // Update Grid Flashes
        for (let i = this.state.gridFlashes.length - 1; i >= 0; i--) {
            this.state.gridFlashes[i].life -= dt * 2.0;
            if (this.state.gridFlashes[i].life <= 0) {
                this.state.gridFlashes.splice(i, 1);
            }
        }

        // --- AMBIENT SPAWNER ---
        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;

        this.ambientTimer += dt;
        // Spawn rate based on type
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            this.spawnAmbientParticle(type);
        }
    }

    private spawnAmbientParticle(type: string) {
        // Spawn randomly in a large area around center
        const x = Math.random() * 1200 - 100;
        const y = Math.random() * 800 - 100;

        const p = this.state.getParticle();
        p.x = x; p.y = y; p.z = Math.random() * 200 + 50; // Keep off ground
        p.type = 'GLOW';

        if (type === 'SNOW') {
            p.color = '#fff';
            p.size = Math.random() * 3 + 1;
            p.vx = 20 + Math.random() * 20; // Wind
            p.vy = 50 + Math.random() * 30; // Fall
            p.life = 3.0; p.maxLife = 3.0;
        } else if (type === 'ASH') {
            p.color = '#78350f'; // Dark grey/brown
            p.size = Math.random() * 4 + 1;
            p.vx = 30 + Math.random() * 30;
            p.vy = 20 + Math.random() * 20;
            p.life = 4.0; p.maxLife = 4.0;
        } else if (type === 'EMBER') {
            p.color = '#fbbf24';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 20;
            p.vy = -30 - Math.random() * 20; // Rise
            p.life = 2.0; p.maxLife = 2.0;
        } else if (type === 'SPORES') {
            p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 10;
            p.vy = (Math.random() - 0.5) * 10; // Float
            p.life = 5.0; p.maxLife = 5.0;
        }

        this.state.particles.push(p);
    }
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Ground Y (The floor)
            const visualY = agent.py - h;

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = agent.py + 1; // Sort base
            op.z = 10;

            op.agent = agent;
            op.tx = agent.px; // Draw X
            op.ty = visualY;  // Draw Y (Ground)
            op.time = globalTime;
            op.uSelected = (highlightAgent === agent);
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }
        const visualY = agent.py - h;
        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // Now Public for the Renderer to call from RenderOp
    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); 
        ctx.scale(scaleFactor, scaleFactor);

        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 
            ctx.restore();

            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
        }

        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(globalTime * 4) * 2;
        }

        ctx.translate(0, bodyFloat);

        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            spawnAlpha = eased;
            whiteOverlay = 1 - eased; 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        // PERF: Removed expensive ctx.filter
        // Use manual alpha for death
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.globalAlpha *= 0.6;
        }
        // Hit flash logic handled AFTER drawing unit body via source-atop

        if (!isSilhouette && agent.hitFlashTimer > 0) {
             whiteOverlay = 0.6; // Simulate brightness
        }

        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Draw Main Unit Body
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
            }

            // PERF: Fast "Hit Flash" using composition instead of Filter
            if (whiteOverlay > 0 && !isSilhouette) {
                ctx.save();
                ctx.globalCompositeOperation = 'source-atop';
                ctx.fillStyle = `rgba(255, 255, 255, ${whiteOverlay})`;
                // Draw a rect covering the approximate unit area. 
                // source-atop ensures it only paints where existing pixels are (the unit body).
                ctx.fillRect(-64, -100, 128, 128); 
                ctx.restore();
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); 

        if (isSelected && !isSilhouette) {
            ctx.save();
            const centerHeight = 50 * scaleFactor;
            ctx.translate(0, -centerHeight); 

            const bracketSize = 60 * scaleFactor;
            ctx.rotate(globalTime * 0.5);
            ctx.lineWidth = 3;
            ctx.strokeStyle = '#22d3ee'; 
            // ctx.shadowColor = '#06b6d4'; // PERF: Removed shadowBlur
            // ctx.shadowBlur = 10;

            const cornerLen = Math.PI / 3;
            for(let i=0; i<4; i++) {
                ctx.beginPath();
                ctx.arc(0, 0, bracketSize, i * (Math.PI/2) - cornerLen/2, i * (Math.PI/2) + cornerLen/2);
                ctx.stroke();
            }

            ctx.rotate(-globalTime * 1.5);
            ctx.lineWidth = 1;
            ctx.setLineDash([5, 5]);
            ctx.beginPath();
            ctx.arc(0, 0, bracketSize * 0.85, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.restore(); 

            ctx.save();
            const bounce = Math.sin(globalTime * 8) * 8;
            const arrowHeight = 110 * scaleFactor;
            ctx.translate(0, -arrowHeight + bounce);

            ctx.fillStyle = '#22d3ee';
            // ctx.shadowColor = '#06b6d4'; // PERF: Removed shadowBlur
            // ctx.shadowBlur = 15;

            ctx.beginPath();
            ctx.moveTo(-10, -15); 
            ctx.lineTo(10, -15);
            ctx.lineTo(0, 5);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -22, 3, 0, Math.PI*2); ctx.fill();

            ctx.restore();
        }

        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

// Helper: Improved Ease for Disciplined Combat
function easeAttack(t: number): number {
    if (t < 0.3) {
        const p = t / 0.3;
        return -0.25 * (p * p); 
    } else if (t < 0.45) {
        const p = (t - 0.3) / 0.15;
        return -0.25 + (1.35 * (p * p * p)); 
    } else {
        const p = (t - 0.45) / 0.55;
        return 1.1 * Math.cos(p * Math.PI / 2);
    }
}

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = THEME_IMPERIAL.energy; 

        // 1. IDLE & BREATHING
        const breathePhase = t * 2.0;
        const floatY = (agent.hp > 0) ? Math.sin(breathePhase) * 2.5 : 0;
        const breatheScale = (agent.hp > 0) ? 1.0 + Math.sin(breathePhase) * 0.02 : 1.0;

        // 2. HIT REACTION
        let hitShakeRot = 0;
        let hitSquashX = 1.0;
        let hitSquashY = 1.0;

        if (agent.hitFlashTimer > 0) {
            hitShakeRot = (Math.random() - 0.5) * 0.15; 
            const trauma = agent.hitFlashTimer * 5; 
            hitSquashY = 1.0 - (trauma * 0.15);
            hitSquashX = 1.0 + (trauma * 0.1);
        }

        // 3. ATTACK ANIMATION
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoilX = 0;
        let bodyRecoilY = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);
            const curve = easeAttack(p);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const kick = Math.max(0, curve);
                armX = kick * 12;
                if (p > 0.3 && p < 0.6) bodyRecoilX = -4 * kick;
                if (p < 0.3) armRot = -0.3 * (p/0.3); 
            } else {
                armRot = curve * (Math.PI / 1.6); 
                if (curve > 0.5) {
                    armX = 18 * curve;
                    bodyRecoilX = 5 * curve; 
                } else if (curve < 0) {
                    bodyRecoilX = -2;
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoilX, floatY);
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        // PERF: Removed ctx.shadowBlur = 10; (Performance Killer)

        ctx.translate(bodyRecoilX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot);
        ctx.scale(breatheScale * hitSquashX, breatheScale * hitSquashY);
        ctx.translate(0, 40);

        drawCape(ctx, t, THEME_IMPERIAL.cape, bodyRecoilX);

        ctx.save();
        ctx.translate(-20, -35);
        ctx.translate(0, Math.sin(t * 2.5 + Math.PI) * 2); 
        if (agent.role === Role.TANK) drawImperialShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawImperialTome(ctx, t);
        ctx.restore();

        drawImperialBody(ctx, agent.role);

        ctx.save();
        ctx.translate(20, -35);
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawImperialWeapon(ctx, agent.role, t);
        ctx.restore();

        ctx.restore();
    }
};

function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, secondary, armorLight, armorDark } = THEME_IMPERIAL;

    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;

    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45);
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25); ctx.fill();

    ctx.save();
    ctx.translate(0, -50);

    if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.strokeStyle = secondary;
        ctx.beginPath(); ctx.arc(0, -5, 16, 0, Math.PI*2); ctx.stroke();
    }

    ctx.fillStyle = armorLight;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) ctx.rect(-10, -12, 20, 18); 
    else ctx.ellipse(0, -2, 9, 11, 0, 0, Math.PI*2);
    ctx.fill(); ctx.stroke();

    ctx.fillStyle = primary;
    ctx.fillRect(-8, -4, 16, 3);

    ctx.restore();
}

function drawCape(ctx: CanvasRenderingContext2D, t: number, color: string, speedX: number) {
    ctx.save();
    ctx.translate(0, -45);
    const drag = -speedX * 1.5;
    const wave = Math.sin(t * 3) * 3;

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-15 + wave + drag, 50);
    ctx.lineTo(15 + wave + drag, 50);
    ctx.lineTo(10, 0);
    ctx.fill();
    ctx.restore();
}

function drawImperialHand(ctx: CanvasRenderingContext2D) {
    ctx.fillStyle = THEME_IMPERIAL.armorDark;
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = THEME_IMPERIAL.secondary;
    ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
}

function drawImperialShield(ctx: CanvasRenderingContext2D) {
    drawImperialHand(ctx);
    ctx.translate(-5, 10);
    ctx.rotate(-Math.PI/12);

    const grad = ctx.createLinearGradient(0, -30, 0, 30);
    grad.addColorStop(0, THEME_IMPERIAL.armorLight);
    grad.addColorStop(1, THEME_IMPERIAL.primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = THEME_IMPERIAL.secondary;
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-15, -30); ctx.lineTo(15, -30);
    ctx.lineTo(15, 10); ctx.lineTo(0, 40); ctx.lineTo(-15, 10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = THEME_IMPERIAL.energy;
    ctx.fillRect(-5, -20, 10, 40);
    ctx.fillRect(-12, -5, 24, 10);
}

function drawImperialTome(ctx: CanvasRenderingContext2D, t: number) {
    drawImperialHand(ctx);
    ctx.translate(0, -10);
    ctx.fillStyle = '#fff';
    ctx.fillRect(-10, -12, 20, 24); 
    ctx.fillStyle = THEME_IMPERIAL.primary;
    ctx.fillRect(-12, -12, 4, 24); 

    if (Math.sin(t*5) > 0) {
        ctx.fillStyle = THEME_IMPERIAL.secondary;
        ctx.fillRect(5, -20, 2, 2);
        ctx.fillRect(8, -25, 2, 2);
    }
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawImperialHand(ctx);

    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI / 2);
        ctx.fillStyle = '#475569';
        ctx.fillRect(-4, -10, 8, 20); 
        ctx.fillStyle = THEME_IMPERIAL.secondary;
        ctx.fillRect(-12, -10, 24, 4); 
        ctx.fillStyle = 'rgba(147, 197, 253, 0.8)';
        ctx.strokeStyle = THEME_IMPERIAL.primary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-6, -10); ctx.lineTo(-4, -70); ctx.lineTo(0, -80);
        ctx.lineTo(4, -70); ctx.lineTo(6, -10);
        ctx.fill(); ctx.stroke();

    } else if (role === Role.TANK) {
        ctx.rotate(Math.PI / 3);
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -10, 6, 50);
        ctx.translate(0, -50);
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 2;
        ctx.fillRect(-12, -15, 24, 30);
        ctx.strokeRect(-12, -15, 24, 30);
        ctx.fillStyle = THEME_IMPERIAL.primary;
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(-20, 0); ctx.lineTo(0, 15); ctx.fill();
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(20, 0); ctx.lineTo(0, 15); ctx.fill();

    } else if (role === Role.RANGER) {
        ctx.translate(10, 0);
        ctx.strokeStyle = THEME_IMPERIAL.armorLight;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5); ctx.stroke();
        ctx.strokeStyle = THEME_IMPERIAL.energy; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(0, -30); ctx.lineTo(0, 30); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(-Math.PI / 6);
        ctx.fillStyle = '#b45309';
        ctx.fillRect(-3, -40, 6, 80);
        ctx.translate(0, -45);
        const float = Math.sin(t * 4) * 3;
        ctx.translate(0, float);
        ctx.fillStyle = role === Role.MAGE ? THEME_IMPERIAL.energy : THEME_IMPERIAL.secondary;
        ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10); ctx.lineTo(-8, 0); ctx.fill();
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

function easeAttack(t: number): number {
    if (t < 0.45) {
        const p = t / 0.45;
        return -0.5 * (p * p * p); 
    } else if (t < 0.55) {
        const p = (t - 0.45) / 0.1;
        return -0.5 + (1.7 * p); 
    } else {
        const p = (t - 0.55) / 0.45;
        return 1.2 - (1.2 * p) + Math.sin(p * Math.PI * 2) * 0.1;
    }
}

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = THEME_COVENANT.secondary; 

        // 1. IDLE & BREATHING
        const noise = Math.sin(t * 7.0) * 0.5 + Math.sin(t * 3.0);
        const floatY = (agent.hp > 0) ? noise * 1.5 : 0;

        const breatheScaleX = (agent.hp > 0) ? 1.0 + Math.sin(t * 4.0) * 0.03 : 1.0;
        const breatheScaleY = (agent.hp > 0) ? 1.0 - Math.sin(t * 4.0) * 0.02 : 1.0;

        // 2. HIT REACTION
        let hitShakeX = 0;
        let hitShakeRot = 0;
        let hitSquashY = 1.0;

        if (agent.hitFlashTimer > 0) {
            hitShakeX = (Math.random() - 0.5) * 4.0;
            hitShakeRot = (Math.random() - 0.5) * 0.3;
            const trauma = agent.hitFlashTimer * 5;
            hitSquashY = 1.0 - (trauma * 0.2); 
        }

        // 3. ATTACK ANIMATION
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoilX = 0;
        let bodyRecoilY = 0;
        let bodyRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);
            const curve = easeAttack(p);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const jerk = Math.max(0, curve);
                armX = jerk * 25; 
                if (p > 0.4 && p < 0.6) {
                    bodyRecoilX = -8; 
                    bodyRecoilY = (Math.random() - 0.5) * 4;
                }
            } else {
                armRot = curve * (Math.PI / 1.3);
                if (curve > 0) {
                    armX = 25 * curve;
                    armY = 15 * curve; 
                    bodyRecoilX = 10 * curve; 
                    bodyRot = 0.1 * curve; 
                } else {
                    bodyRecoilX = -5; 
                    bodyRot = -0.1;   
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoilX, floatY);
            ctx.beginPath();
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); ctx.closePath();
            ctx.stroke();
            ctx.restore();
            return;
        }

        // PERF: Removed ctx.shadowBlur = 10;

        ctx.translate(bodyRecoilX + hitShakeX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot + bodyRot);
        ctx.scale(breatheScaleX, breatheScaleY * hitSquashY);
        ctx.translate(0, 40);

        drawSpikes(ctx, t);

        ctx.save();
        ctx.translate(-22, -30);
        ctx.translate(0, Math.sin(t * 3) * 2);
        if (agent.role === Role.TANK) drawCovenantShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawCovenantTotem(ctx, t);
        ctx.restore();

        drawCovenantBody(ctx, agent.role);

        ctx.save();
        ctx.translate(22, -30); // Shoulder
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawCovenantWeapon(ctx, agent.role, t);
        ctx.restore();

        ctx.restore();
    }
};

function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, armorDark, armorBase, accent, secondary } = THEME_COVENANT;

    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, armorDark);
    grad.addColorStop(1, '#000');

    ctx.fillStyle = grad;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1;

    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); 
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = secondary;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();

    ctx.save();
    ctx.translate(0, -48);

    ctx.fillStyle = armorDark;
    ctx.beginPath();
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();

    ctx.fillStyle = '#fca5a5';
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = THEME_COVENANT.spike;
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}

function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    ctx.fillStyle = THEME_COVENANT.armorDark;
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}

function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);

    ctx.fillStyle = THEME_COVENANT.armorBase;
    ctx.strokeStyle = THEME_COVENANT.secondary;
    ctx.lineWidth = 2;

    ctx.beginPath();
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = THEME_COVENANT.accent;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}

function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10);
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);
    ctx.translate(0, -45);
    ctx.fillStyle = THEME_COVENANT.secondary;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
}

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);

    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI / 4);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-3, -10, 6, 60);
        ctx.translate(0, -60);
        ctx.fillStyle = '#52525b';
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(-25, -10);
        ctx.quadraticCurveTo(-15, 10, -25, 30);
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();

    } else if (role === Role.TANK) {
        ctx.rotate(Math.PI / 3);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-4, -5, 8, 20);
        ctx.fillStyle = THEME_COVENANT.accent;
        ctx.beginPath();
        ctx.moveTo(-10, -10); ctx.lineTo(-10, -60);
        ctx.lineTo(20, -60); ctx.lineTo(20, -10); ctx.lineTo(0, 0);
        ctx.fill();
        ctx.strokeStyle = THEME_COVENANT.secondary; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();

    } else if (role === Role.RANGER) {
        ctx.rotate(-Math.PI / 2);
        ctx.fillStyle = THEME_COVENANT.armorDark;
        ctx.fillRect(-5, -30, 10, 40);
        ctx.strokeStyle = THEME_COVENANT.accent; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25); ctx.stroke();
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(Math.PI / 6);
        ctx.fillStyle = '#450a0a';
        ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(-5, -30); ctx.lineTo(0, -50); ctx.lineTo(5, -30); ctx.fill();
        ctx.fillStyle = THEME_COVENANT.secondary;
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
    }
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    // We are at Ground Level (0,0) in the scaled context.
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    // Rotating Rune Ring - Clear indication of ground position
    ctx.save();
    ctx.scale(1, 0.58); // Isometric flat on ground
    ctx.rotate(t * 0.5);

    // Outer dashed ring
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    // Only visible if unit is airborne to show connection
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); // Fade out near unit feet

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        // Draw Main Tether Line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        // Draw Moving Energy Pulses up the tether
        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; // 0 to 1, faster speed
            const px = feetX * p;
            const py = feetY * p;

            // Draw small horizontal dash/disk traveling up
            // Scale based on height to simulate perspective
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    // MUTUALLY EXCLUSIVE: Only draw if NOT Poly'd and NOT Stasis
    if (agent.banished && agent.visualStatus !== 'POLYMORPH' && agent.visualStatus !== 'STASIS') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            // const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            // PERF: Removed shadowBlur for stun stars
            // ctx.shadowColor = '#fbbf24';
            // ctx.shadowBlur = 10;

            // Draw Star
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();
            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;
        // PERF: Removed shadowBlur for Silence rune
        // ctx.shadowColor = '#c084fc';
        // ctx.shadowBlur = 10;

        // Rune Box
        ctx.beginPath();
        ctx.rect(-15, -10, 30, 20);
        ctx.fill();
        ctx.stroke();

        // "X" or Rune Text
        ctx.beginPath();
        ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
        ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
        ctx.stroke();
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

// Helper: Chaos color detection
function isChaosStyle(color: string): boolean {
    const c = color.toLowerCase();
    return c.includes('#dc') || c.includes('#ef') || c.includes('#b9') || c.includes('#45') || 
           c.includes('#7f') || c.includes('#4c') || c.includes('#a3') || c.includes('#58') ||
           c.includes('#1c');
}

// Pseudo-Random Noise generator for textures
function pseudoNoise(x: number, y: number, seed: number) {
    const n = Math.sin(x * 12.9898 + y * 78.233 + seed) * 43758.5453;
    return n - Math.floor(n);
}

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;
         const isChaos = isChaosStyle(color);

         // Improved Gradient for softer falloff (Fixes banding)
         const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
         grad.addColorStop(0, '#fff');        
         grad.addColorStop(0.15, color); // Tight core
         grad.addColorStop(0.4, color);  
         grad.addColorStop(1, 'rgba(0,0,0,0)'); 

         ctx.fillStyle = grad;

         if (isChaos) {
             // Chaos: Unstable plasma blob
             ctx.beginPath();
             const spikes = 12;
             for(let i=0; i<spikes; i++) {
                 const angle = (i / spikes) * Math.PI * 2;
                 const rad = r * (0.7 + Math.random() * 0.3);
                 const x = cx + Math.cos(angle) * rad;
                 const y = cy + Math.sin(angle) * rad;
                 if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
             }
             ctx.closePath();
             ctx.fill();
         } else {
             // Order: Perfect Sphere
             ctx.beginPath(); 
             ctx.arc(cx, cy, r, 0, Math.PI * 2); 
             ctx.fill();

             // Soft Cross Flare
             ctx.fillStyle = '#fff';
             ctx.globalAlpha = 0.5;
             ctx.beginPath();
             ctx.ellipse(cx, cy, r * 0.8, r * 0.1, 0, 0, Math.PI*2);
             ctx.fill();
             ctx.beginPath();
             ctx.ellipse(cx, cy, r * 0.1, r * 0.8, 0, 0, Math.PI*2);
             ctx.fill();
         }

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.6, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3;

        for(let i=0; i<12; i++) {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * (FOG_SIZE * 0.3);
            const size = FOG_SIZE * (0.1 + Math.random() * 0.2);

            ctx.beginPath(); 
            ctx.arc(cx + Math.cos(angle)*dist, cy + Math.sin(angle)*dist, size, 0, Math.PI*2); 
            ctx.fill();
        }

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        if (isChaos) {
            ctx.beginPath();
            const points = 9;
            for(let i=0; i<=points; i++) {
                const angle = i * (Math.PI * 2 / points);
                const r = radius * (0.85 + Math.random() * 0.3); 
                const x = cx + Math.cos(angle) * r;
                const y = cy + Math.sin(angle) * r;
                if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.closePath();
            ctx.stroke();

            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy); 
            ctx.quadraticCurveTo(cx, cy - 15, cx + 25, cy);
            ctx.quadraticCurveTo(cx, cy + 15, cx - 25, cy);
            ctx.stroke();

            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI*2); ctx.fill();

        } else {
            ctx.beginPath(); 
            ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
            ctx.stroke();

            ctx.lineWidth = 1.5;
            if (isUlt) {
                const drawPoly = (sides: number, r: number, offset: number) => {
                    ctx.beginPath();
                    for (let i = 0; i <= sides; i++) {
                        const angle = offset + (i * Math.PI * 2) / sides;
                        const x = cx + Math.cos(angle) * r;
                        const y = cy + Math.sin(angle) * r;
                        if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.stroke();
                };

                drawPoly(3, radius, -Math.PI/2); 
                drawPoly(3, radius, Math.PI/2);  

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.5, 0, Math.PI*2); ctx.stroke();

            } else {
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(Math.PI/4);
                ctx.strokeRect(-radius * 0.7, -radius * 0.7, radius * 1.4, radius * 1.4);
                ctx.restore();

                ctx.beginPath(); ctx.arc(cx, cy, radius * 0.3, 0, Math.PI*2); ctx.stroke();
            }
        }

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.shadowColor = color;
        ctx.shadowBlur = 12;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                ctx.strokeStyle = isChaos ? '#a8a29e' : '#e2e8f0'; 
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(75, cy); ctx.stroke();

                ctx.fillStyle = isChaos ? '#7f1d1d' : '#f0f9ff';
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(85, cy); 
                    ctx.lineTo(65, cy - 8); ctx.lineTo(70, cy); ctx.lineTo(65, cy + 8);
                } else {
                    ctx.moveTo(90, cy); ctx.lineTo(70, cy - 6); ctx.lineTo(70, cy + 6);
                }
                ctx.closePath();
                ctx.fill();

                ctx.strokeStyle = color;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy - 10);
                    ctx.moveTo(20, cy); ctx.lineTo(5, cy + 10);
                } else {
                    ctx.moveTo(15, cy - 5); ctx.lineTo(5, cy); ctx.lineTo(15, cy + 5);
                }
                ctx.stroke();
                break;

            case 'FIREBALL':
            case 'BOMB':
                const coreGrad = ctx.createRadialGradient(cx+20, cy, 0, cx+20, cy, 15);
                coreGrad.addColorStop(0, '#fff');
                coreGrad.addColorStop(0.5, color);
                coreGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = coreGrad;

                ctx.beginPath(); ctx.arc(cx + 20, cy, 14, 0, Math.PI * 2); ctx.fill();

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.beginPath();
                if (isChaos) {
                    ctx.moveTo(cx + 20, cy - 12);
                    ctx.lineTo(cx, cy - 20); ctx.lineTo(cx - 20, cy - 5);
                    ctx.lineTo(cx - 35, cy);
                    ctx.lineTo(cx - 20, cy + 8); ctx.lineTo(cx, cy + 22);
                    ctx.lineTo(cx + 20, cy + 12);
                } else {
                    ctx.ellipse(cx + 5, cy, 35, 12, 0, 0, Math.PI * 2);
                }
                ctx.fill();
                break;

            case 'SLASH':
                // New specialized slash shape for 2-tile attacks
                ctx.translate(cx, cy);
                // Draw a crescent moon shape
                ctx.beginPath();
                ctx.arc(0, 0, 30, -Math.PI/3, Math.PI/3, false);
                ctx.arc(-10, 0, 30, Math.PI/3, -Math.PI/3, true);
                ctx.closePath();
                ctx.fillStyle = '#fff';
                ctx.fill();

                ctx.shadowColor = color;
                ctx.shadowBlur = 15;
                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.stroke();
                break;

            case 'BOLT':
            case 'BEAM':
            default:
                if (isChaos) {
                    ctx.fillStyle = '#1c1917'; 
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 3;

                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy);
                    ctx.lineTo(cx + 10, cy - 15);
                    ctx.lineTo(cx - 10, cy - 5);
                    ctx.lineTo(cx - 30, cy);
                    ctx.lineTo(cx - 10, cy + 5);
                    ctx.lineTo(cx + 10, cy + 15);
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();

                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy - 12);
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx + 45, cy + 12);
                    ctx.stroke();

                } else {
                    const boltGrad = ctx.createRadialGradient(cx, cy, 2, cx, cy, 25); 
                    boltGrad.addColorStop(0, '#fff');
                    boltGrad.addColorStop(0.5, color);
                    boltGrad.addColorStop(1, 'transparent');
                    ctx.fillStyle = boltGrad;
                    ctx.beginPath(); ctx.arc(cx, cy, 25, 0, Math.PI * 2); ctx.fill();

                    ctx.fillStyle = '#fff';
                    ctx.shadowColor = '#fff';
                    ctx.beginPath();
                    ctx.moveTo(cx + 35, cy); ctx.lineTo(cx, cy - 12);
                    ctx.lineTo(cx - 15, cy); ctx.lineTo(cx, cy + 12);
                    ctx.closePath();
                    ctx.fill();

                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.shadowBlur = 5;
                    ctx.beginPath(); 
                    ctx.ellipse(cx, cy, 15, 8, 0, 0, Math.PI*2); 
                    ctx.stroke();
                }
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;
        const isChaos = isChaosStyle(color);

        ctx.scale(1, 0.5); 

        const rings = 5;
        for(let i = 0; i < rings; i++) {
            const r = (50 / rings) * (i + 1);
            const alpha = 1.0 - (i / rings);

            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2 + Math.random() * 2;
            ctx.globalAlpha = alpha * 0.5;

            const segments = 24;
            for(let j=0; j<=segments; j++) {
                const a = (j/segments) * Math.PI * 2;
                const offset = pseudoNoise(j, i, 100) * 10;
                const radius = r + offset;
                const px = cx + Math.cos(a) * radius;
                const py = cy * 2 + Math.sin(a) * radius;
                if (j===0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        }

        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 25);
        grad.addColorStop(0, isChaos ? '#000' : '#fff'); 
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(cx, cy * 2, 25, 0, Math.PI*2); ctx.fill();

        return canvas;
    }
};

import { VFXFactory } from "./graphics/VFXFactory";
import { UIFactory } from "./graphics/UIFactory";

const cache: Map<string, HTMLCanvasElement> = new Map();

export const AssetManager = {
    // New: Optimized Glow Sprite (Small) for replacement of shadowBlur
    getGlowSprite(color: string): HTMLCanvasElement {
        const key = `GLOW_SPRITE_${color}`;
        if (!cache.has(key)) cache.set(key, VFXFactory.generateGlowOrb(color, 64));
        return cache.get(key)!;
    },

    // New: Pre-rendered Fog
    getFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (!cache.has(key)) cache.set(key, VFXFactory.generateFogCloud(color));
        return cache.get(key)!;
    },

    // VFX: Projectiles
    getProjectile(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (!cache.has(key)) {
            // Fallback to BOLT if unknown
            const v = ['ARROW', 'FIREBALL', 'BOLT', 'BOMB'].includes(visual) ? visual : 'BOLT';
            cache.set(key, VFXFactory.generateProjectileSprite(v, color));
        }
        return cache.get(key)!;
    },

    // UI: Skill Icons
    getSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const key = `SK_ICON_${visual}_${color}`;
        if (!cache.has(key)) cache.set(key, UIFactory.generateSkillIcon(visual, color));
        return cache.get(key)!;
    },

    // UI: Status Icons
    getStatusIcon(type: string): HTMLCanvasElement {
        const key = `STATUS_${type}`;
        if (!cache.has(key)) cache.set(key, UIFactory.generateStatusIcon(type));
        return cache.get(key)!;
    },

    // VFX: Ground Decals
    getBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_${color}_V2`; // V2 for updated style
        if (!cache.has(key)) cache.set(key, VFXFactory.generateBlastZone(color));
        return cache.get(key)!;
    },

    // VFX: Casting Circles
    getMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const key = `MAGIC_CIRCLE_${color}_${isUlt}`;
        if (!cache.has(key)) cache.set(key, VFXFactory.generateMagicCircle(color, isUlt));
        return cache.get(key)!;
    }
};

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS (Fixes "Floating" feeling) ---
        // We are currently at [x, GroundY - Z].
        // To draw shadow at GroundY, we must translate down by Z.
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash

            // Dynamic shadow opacity based on height
            const shadowAlpha = Math.max(0, 0.4 - (p.z / 400));
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath();
                ctx.arc(0, 0, shadowSize, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.restore();
        }

        if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;

                // Perspective Scale: Things closer to camera (higher Z) look slightly bigger
                const perspective = 1.0 + (p.z * 0.002);

                ctx.rotate(p.rotation);
                const scale = (p.size / 64) * perspective; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'GLOW') {
            // New Handler for Ambient Effects (Snow, Ash, Embers)
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.8;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'CHIP') {
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4);

            // Motion Stretch
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(2.0, 1 + speed / 1000);
            ctx.scale(stretch, 1/stretch);

            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;

            // Spin blur effect
            ctx.shadowColor = p.color;
            ctx.shadowBlur = p.vRotation > 5 ? 10 : 0;

            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

            // Highlight edge
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            // Softer Alpha
            ctx.globalAlpha = (1 - progress) * 0.3;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 

            // Motion Stretch for Sparks
            const vel = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            if (vel > 50) {
                const angle = Math.atan2(p.vy, p.vx);
                ctx.rotate(angle);
                ctx.scale(1 + vel/500, 0.5);
            }

            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG (Procedural)
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        // Hex Geometry (Matches TerrainRenderer)
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; // ISO squashing
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); // Smooth fade in/out

        ctx.save();

        if (isChaos) {
            // RED: CRACKED EARTH + RISING MIASMA

            // 1. Ground Cracks (Base)
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);

            drawHex();
            ctx.clip();

            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();

            ctx.strokeStyle = p.color; // Hot red
            ctx.lineWidth = 2;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 10;
            ctx.globalAlpha = fade;

            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();

            // 2. Rising Miasma (Volumetric Fog)
            ctx.globalCompositeOperation = 'lighter';

            const puffs = 3;
            for(let i=0; i<puffs; i++) {
                const t = (Date.now() / 1000 + i * 100) % 1;
                const yPos = 10 - t * 60; 
                const scale = 1 + t * 0.5;
                const puffAlpha = fade * (1 - t);

                ctx.globalAlpha = puffAlpha * 0.4;
                ctx.fillStyle = p.color;

                ctx.beginPath();
                ctx.ellipse((Math.sin(t*10 + i)*5), yPos, 15 * scale, 8 * scale, 0, 0, Math.PI*2);
                ctx.fill();
            }

        } else {
            // BLUE: HOLY CONSECRATION + LIGHT DUST

            // 1. Clean Hex Outline
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 15;

            drawHex();
            ctx.stroke();

            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();

            // 2. Vertical Light Beams (Stationary)
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#fff';

            const beams = 4;
            for(let i=0; i<beams; i++) {
                const angle = (Date.now() / 2000 + i * (Math.PI*2/beams)) % (Math.PI*2);
                const r = 15;
                const px = Math.cos(angle) * r;
                const py = Math.sin(angle) * r * 0.58;

                const beamHeight = 40 + Math.sin(Date.now()/500 + i)*10;

                const grad = ctx.createLinearGradient(0, py, 0, py - beamHeight);
                grad.addColorStop(0, `rgba(255,255,255,${fade * 0.5})`);
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.fillStyle = grad;
                ctx.fillRect(px - 1, py - beamHeight, 2, beamHeight);
            }
        }

        ctx.restore();
    },

    // 🏛️ BLUE: DIVINE PILLAR (High-End Technical Art)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;

        let alpha = 0;
        if (lifeRatio > 0.9) alpha = (1 - lifeRatio) * 10; // 0.1s fade in
        else alpha = Math.pow(lifeRatio, 0.5); // Slow decay

        const maxHeight = 1200;
        const currentHeight = maxHeight * (progress < 0.1 ? progress * 10 : 1.0);
        const width = p.size;

        ctx.save();

        // Layer 1: Ground Seal (The Impact Point)
        ctx.save();
        ctx.scale(1, 0.55);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = alpha;

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 3;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;
        ctx.beginPath(); ctx.arc(0, 0, width * 0.8, 0, Math.PI*2); ctx.stroke();

        const wave = (progress * 2) % 1;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * (1 - wave);
        ctx.beginPath(); ctx.arc(0, 0, width * (0.8 + wave * 0.5), 0, Math.PI*2); ctx.stroke();
        ctx.restore();

        // Layer 2: The Beam (Vertical Gradient)
        ctx.globalCompositeOperation = 'screen';

        const coreW = width * 0.3;
        const coreGrad = ctx.createLinearGradient(0, 0, 0, -currentHeight);
        coreGrad.addColorStop(0, 'rgba(255,255,255,0)');
        coreGrad.addColorStop(0.1, 'rgba(255,255,255,0.9)');
        coreGrad.addColorStop(0.8, 'rgba(255,255,255,0.0)');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-coreW/2, -currentHeight, coreW, currentHeight);

        const glowW = width;
        const glowGrad = ctx.createLinearGradient(-glowW, 0, glowW, 0); // Horizontal fade
        glowGrad.addColorStop(0, 'rgba(0,0,0,0)');
        glowGrad.addColorStop(0.2, p.color);
        glowGrad.addColorStop(0.5, 'rgba(255,255,255,0.5)');
        glowGrad.addColorStop(0.8, p.color);
        glowGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.save();
        const vMask = ctx.createLinearGradient(0, 0, 0, -currentHeight);
        vMask.addColorStop(0, 'rgba(0,0,0,0)');
        vMask.addColorStop(0.1, 'rgba(0,0,0,1)'); 

        ctx.fillStyle = glowGrad;
        ctx.globalAlpha = alpha * 0.6;
        const jitter = Math.random() * 10;
        ctx.fillRect(-(glowW + jitter)/2, -currentHeight, glowW + jitter, currentHeight);
        ctx.restore();

        // Layer 3: Interference Lines (Rising Energy)
        ctx.globalAlpha = alpha * 0.5;
        ctx.fillStyle = '#fff';
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const yPos = -((Date.now()/500 + i/lines) % 1) * currentHeight;
            const hRatio = Math.abs(yPos) / currentHeight;
            const lineAlpha = 1 - Math.pow(2 * hRatio - 1, 2); 

            if (lineAlpha > 0.1) {
                ctx.globalAlpha = alpha * lineAlpha * 0.8;
                const lineW = width * (0.5 + Math.random()*0.5);
                ctx.fillRect(-lineW/2, yPos, lineW, 2 + Math.random() * 4);
            }
        }

        ctx.restore();
    },

    // 🩸 RED: BLOOD RITUAL (CHAOS)
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // 1. The Void (Ground Hole)
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); // Black center
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 2. Cracks / Runes
         ctx.strokeStyle = p.color; // Red/Orange
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();

         // 3. Rising Dark Miasma (Noise)
         ctx.globalCompositeOperation = 'lighter'; // Glowy smoke
         ctx.fillStyle = p.color;
         const bubbles = 5;
         for(let i=0; i<bubbles; i++) {
             const bAngle = i * (Math.PI * 2 / bubbles) + progress * 2;
             const dist = r * 0.6;
             const bx = Math.cos(bAngle) * dist;
             const by = Math.sin(bAngle) * dist;
             const bSize = r * 0.3 * Math.sin(progress * 10 + i);

             ctx.globalAlpha = alpha * 0.3;
             ctx.beginPath(); ctx.arc(bx, by, Math.abs(bSize), 0, Math.PI*2); ctx.fill();
         }

         ctx.restore();

         // 4. Vertical "Heat" Haze (Not a pillar)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;

         ctx.beginPath();
         ctx.moveTo(-r/2, 0); 
         ctx.lineTo(-r/4, -300);
         ctx.lineTo(r/4, -300);
         ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 

        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            // Jagged
            ctx.globalCompositeOperation = 'source-over'; // Darker/Physical
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            // Smooth
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

// --- 1. FACTION ULTIMATES ---

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    // Blue/Imperial: Clean, Vertical, Geometric
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100; // Radius
    p.type = 'PILLAR'; // Uses "Order" render style
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    // Red/Covenant: Chaotic, Ground-breaking, Dark
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; // Radius
    p.type = 'DOMAIN'; // Re-using Domain type but with chaos flag in renderer
    p.delay = 0;
    system.state.particles.push(p);

    // Add rising "Blood/Darkness" debris
    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; // Rising slow
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; // Obsidian chunks
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// --- 2. GRID CONSISTENCY ---

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    // Replaced shockwaves with "GRID_FIELD" which is a stationary volumetric effect
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;

    // Duration needs to be long enough to feel like a "Zone" logic execution
    // Standard impact duration + fade
    p.life = 1.2; p.maxLife = 1.2;
    p.color = color;
    p.size = 36; // Matches HEX_SIZE approx
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);

    // Add a quick flash for immediate impact feel
    if (Math.random() > 0.5) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150; // Fly up
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    // Spawns smoke/clouds that persist
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;

        // Drift slowly
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; // Rise slowly

        p.life = duration + Math.random(); 
        p.maxLife = p.life;
        p.color = color;
        p.size = 20 + Math.random() * 20;
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;

        system.state.particles.push(p);
    }
}

// --- 3. EXISTING HELPERS (Preserved) ---

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = isPhysical ? 8 : 10;
    const spread = 0.8; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 250 + Math.random() * 250; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.6 + Math.random() * 0.4; 
        p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 3 + Math.random() * 3; 
        p.type = 'CHIP'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 20;
        p.delay = 0;

        system.state.particles.push(p);
    }
    spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 
        p.vx = Math.cos(angle) * dist; p.vy = Math.sin(angle) * dist; p.vz = vZ;
        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff'; p.size = 64 * scale; 
        p.type = 'SPRITE'; p.image = img;
        p.rotation = Math.random() * Math.PI * 2; p.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(p);
    };

    const baseColor = '#52525b';
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 50 + Math.random() * 100; 
        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor; p.size = 10 + Math.random() * 10;
        p.type = 'SHARD'; p.rotation = angle; p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    // Spawn Icon (Head)
    spawnSprite(assets.icon, 0.6, 70, 300);   

    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        const angle = Math.random() * Math.PI * 2;
        const speed = 50 + Math.random() * 150;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 150 + Math.random() * 150;
        p.life = 2.0; p.maxLife = 2.0;
        p.color = coreColor; p.size = 6 + Math.random() * 6;
        p.type = 'DEBRIS'; 
        p.rotation = Math.random() * Math.PI; p.vRotation = (Math.random()-0.5) * 15;
        system.state.particles.push(p);
    }
    addDecal(system, x, y, '#000'); 
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 
    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 
        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 20 + Math.random() * 30;
        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; p.delay = 0;
        system.state.particles.push(p);
    }
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { Role, Team } from "../types";
import { PALETTE } from "../constants";
import { UnitFactory } from "./graphics/UnitFactory";
import { EnvironmentFactory } from "./graphics/EnvironmentFactory";

const cache: Map<string, any> = new Map();

export interface UnitAssets {
    base: HTMLCanvasElement; // Pre-rendered base
    icon: HTMLCanvasElement;   // Pre-rendered class icon
    color: string;           // Glow color
}

// ==========================================
// Sprite Manager (Cache & Facade)
// ==========================================
export const SpriteManager = {
    getUnitImages(role: Role, team: Team): UnitAssets {
        // Updated keys to force refresh with new designs
        const keyBase = `TOKEN_BASE_${team}_V3`; 
        let base = cache.get(keyBase);
        if (!base) {
            base = UnitFactory.generateTokenBase(team);
            cache.set(keyBase, base);
        }

        const keyIcon = `ROLE_ICON_${role}_${team}_V3`;
        let icon = cache.get(keyIcon);
        if (!icon) {
            icon = UnitFactory.generateRoleIcon(role, team);
            cache.set(keyIcon, icon);
        }

        return {
            base: base,
            icon: icon,
            color: PALETTE.TEAMS[team].glow
        };
    },

    getObstacleSprite(styleKey: string = 'WALL'): HTMLCanvasElement {
        const key = `OBSTACLE_${styleKey}`;
        if (cache.has(key)) return cache.get(key)!;

        const canvas = EnvironmentFactory.generateObstacle(styleKey);
        cache.set(key, canvas);
        return canvas;
    },

    getSpecialModel(type: 'SHEEP' | 'ICE'): HTMLCanvasElement {
        const key = `MODEL_${type}`;
        if (cache.has(key)) return cache.get(key)!;

        let canvas;
        if (type === 'SHEEP') {
            canvas = UnitFactory.generateSheep();
        } else {
            canvas = EnvironmentFactory.generateIceBlock();
        }

        cache.set(key, canvas);
        return canvas;
    }
};

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 36; 
        const isBlue = team === Team.BLUE;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); // Isometric projection

        // 1. Drop Shadow (Heavy grounding)
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.beginPath(); 
        ctx.arc(0, 8, radius + 2, 0, Math.PI*2); 
        ctx.fill();

        // 2. Physical Material Body
        if (isBlue) {
            // IMPERIAL: White Marble & Gold
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#f8fafc'); // White marble
            grad.addColorStop(1, '#94a3b8'); // Grey shading
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

            // Gold Rim (Solid metal)
            ctx.strokeStyle = '#d97706'; // Dark Gold border
            ctx.lineWidth = 6;
            ctx.stroke();
            ctx.strokeStyle = '#fbbf24'; // Bright Gold highlight
            ctx.lineWidth = 3;
            ctx.stroke();

            // Inner Tech Circuit (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.6, 0, Math.PI*2);
            ctx.fillStyle = '#1e3a8a'; // Dark Blue recessed area
            ctx.fill();
            ctx.strokeStyle = '#60a5fa'; // Glowing blue line
            ctx.lineWidth = 2;
            ctx.stroke();

        } else {
            // COVENANT: Dark Iron & Magma
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#27272a'); // Iron
            grad.addColorStop(1, '#000000'); 
            ctx.fillStyle = grad;

            // Jagged Shape base
            ctx.beginPath();
            const sides = 8;
            for(let i=0; i<=sides; i++) {
                const a = (i/sides) * Math.PI*2;
                const r = radius * (i%2===0 ? 1.0 : 0.9); // Gear/Spike shape
                const x = Math.cos(a)*r;
                const y = Math.sin(a)*r;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // Iron Rim
            ctx.strokeStyle = '#52525b';
            ctx.lineWidth = 4;
            ctx.stroke();

            // Inner Magma Core (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.5, 0, Math.PI*2);
            ctx.fillStyle = '#450a0a'; // Dark Red
            ctx.fill();
            ctx.strokeStyle = '#ef4444'; // Glowing Red
            ctx.lineWidth = 2;
            ctx.stroke();
        }

        // 3. Projector Lens Flare (Center)
        // This suggests the unit is being projected FROM here
        ctx.fillStyle = isBlue ? '#fff' : '#fecaca';
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;

        // Emissive holographic text color
        const color = team === Team.BLUE ? '#e0f2fe' : '#fecaca';
        const shadowColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.shadowColor = shadowColor;
        ctx.shadowBlur = 10;
        ctx.lineWidth = 3;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.translate(cx, cy);

        // Scale down to fit nicely in 64x64
        const scale = 1.2;
        ctx.scale(scale, scale);

        // Vector Drawings instead of Emojis
        ctx.beginPath();
        if (role === Role.TANK) {
            // Shield Icon
            ctx.moveTo(0, 12);
            ctx.lineTo(9, 12);
            ctx.lineTo(12, -6);
            ctx.lineTo(0, -12);
            ctx.lineTo(-12, -6);
            ctx.lineTo(-9, 12);
            ctx.closePath();
            ctx.stroke();
            // Inner cross
            ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(0, 6); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-6, 0); ctx.lineTo(6, 0); ctx.stroke();

        } else if (role === Role.WARRIOR) {
            // Crossed Swords
            const drawSword = () => {
                ctx.moveTo(-8, -8); ctx.lineTo(8, 8); // Blade
                ctx.moveTo(-5, -8); ctx.lineTo(-8, -5); // Hilt Guard
                ctx.moveTo(5, 8); ctx.lineTo(8, 5); // Tip detail
            };
            ctx.save();
            ctx.beginPath();
            drawSword();
            ctx.stroke();
            ctx.scale(-1, 1); // Flip for X
            ctx.beginPath();
            drawSword();
            ctx.stroke();
            ctx.restore();

        } else if (role === Role.RANGER) {
            // Bow & Arrow
            ctx.beginPath();
            ctx.arc(0, 0, 12, -Math.PI/2, Math.PI/2); // Bow string
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(0, -14); ctx.lineTo(0, 14); // Bow Riser
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(14, 0); // Arrow
            ctx.lineTo(10, -4); ctx.moveTo(14, 0); ctx.lineTo(10, 4); // Arrow head
            ctx.stroke();

        } else if (role === Role.MAGE) {
            // Staff / Spark
            ctx.beginPath();
            ctx.moveTo(-10, 10); ctx.lineTo(10, -10); // Staff
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(10, -10, 5, 0, Math.PI*2); // Orb
            ctx.stroke();
            // Sparkles
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(14, -14, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(6, -6, 1.5, 0, Math.PI*2); ctx.fill();

        } else if (role === Role.SUPPORT) {
            // Cross / Ankh
            ctx.beginPath();
            ctx.moveTo(0, -12); ctx.lineTo(0, 12);
            ctx.moveTo(-8, -4); ctx.lineTo(8, -4);
            ctx.stroke();
            // Circle top
            ctx.beginPath(); ctx.arc(0, -8, 4, 0, Math.PI*2); ctx.stroke();
        }

        return canvas;
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

export enum Team {
    BLUE = 0,
    RED = 1
}

export enum Role {
    TANK = 'TANK',
    WARRIOR = 'WARRIOR',
    RANGER = 'RANGER',
    MAGE = 'MAGE',
    SUPPORT = 'SUPPORT'
}

export enum MovementType {
    GROUND = 0,
    FLYING = 1
}

export enum AnimState {
    IDLE = 0,
    COMBAT_IDLE = 1,
    ATTACK = 2,
    HIT = 3,
    DEAD = 4,
    STUN = 5,
    MOVE = 6
}

export interface Hex {
    q: number;
    r: number;
}

export interface Point {
    x: number;
    y: number;
}

// Scene / Environment Types
export interface SceneTheme {
    id: string;
    name: string;
    background: string; // Sky Top Color
    horizon: string;    // Sky Bottom/Horizon Color (New)
    fogColor: string;   // Low-lying fog color (New)
    textureType: 'VOID' | 'FOREST' | 'ICE' | 'MAGMA' | 'DESERT';
    obstacleStyle: string; 
    hexStroke: string; 
    ambientType: 'NONE' | 'SNOW' | 'ASH' | 'SPORES' | 'RAIN' | 'EMBER';
    ambientColor: string;
    bgFeature: 'NONE' | 'SKY_RIVER' | 'AURORA' | 'CANOPY' | 'HEAT_WAVE' | 'DUNES';
}

// Data Models
export interface Skill {
    id: string;
    tag: 'BASIC' | 'ACTIVE' | 'ULT';
    role: Role;
    team?: Team; // Optional: If specified, only this team can learn it
    name: string;
    desc?: string; // For Tooltips
    range: number;
    cast: number;
    cd: number;
    cost: number;
    gain: number;
    type: 'SINGLE' | 'AOE';
    aoeRadius?: number; // Default 1 if not specified
    power: number;
    color: string;

    // Control Effects (Slot 1)
    ccType?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE';
    ccDur?: number;
    ccForce?: number;

    // Control Effects (Slot 2) - NEW: Allows composite effects like Knockback + Stun
    ccType2?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE';
    ccDur2?: number;
    ccForce2?: number;

    // Special Combat Effects (Slot 1)
    effectType?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal?: number; // e.g. 0.5 for 50% Vamp, 1.5 for 50% bonus Execute dmg

    // Special Combat Effects (Slot 2)
    effectType2?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal2?: number;

    projectileSpeed?: number; // 0 = Instant
    visual?: 'ARROW' | 'FIREBALL' | 'BOLT' | 'SLASH' | 'SMASH' | 'BEAM' | 'BOMB';
}

export interface UnitStats {
    role: Role;
    maxHp: number;
    maxMp: number;
    moveSpeed: number; // Tiles per second. 1.0 = 1 tile/sec
    movementType: MovementType; // Ground or Flying
}

export interface ObstacleDef {
    id: string;
    name: string;
    blocksVision: boolean;
    blocksMovement: boolean;
    blocksFlying?: boolean; // New: If true, blocks even flying units (High Towers/Pillars)
}

// Logic State Types
export enum NodeState {
    SUCCESS = 'S',
    FAILURE = 'F',
    RUNNING = 'R'
}

export type LogActionType = 'MOVE' | 'CAST' | 'HIT' | 'DECISION' | 'DEATH' | 'SYSTEM' | 'HEAL' | 'CC';

export interface LogEntry {
    id: string;
    time: string;
    turn: number; // Battle tick or frame count
    agentId: string; // "Who"
    team: Team | undefined;
    location: string; // "Where" (e.g., "(10, 5)")
    actionType: LogActionType;
    actionName: string; // "What" (e.g., "Fireball", "MoveTo")
    targetInfo?: string; // "To Whom" (e.g., "Tank-A @ (12,5)")
    detail: string; // Narrative details
    visualColor?: string; // For UI highlighting

    // Legacy support fields (optional)
    action?: string;
    target?: string;
    loc?: string;
}

export interface Projectile {
    id: string;
    x: number;
    y: number;
    startX: number; // New: For Height Interpolation
    startY: number; // New: For Height Interpolation
    targetId: string;
    targetPos: Point;
    speed: number;
    skill: Skill;
    sourceId: string;
    team: Team;
    trail: Point[];
}

// Event System (Bridge between Logic and Visuals)
// Added VISUAL_BEAM for strict enforcement of instant ranged attacks
export type GameEventType = 'DAMAGE' | 'HEAL' | 'CC_APPLIED' | 'CAST_START' | 'CAST_FINISH' | 'PROJECTILE_SPAWN' | 'PROJECTILE_HIT' | 'DEATH' | 'SPAWN' | 'VISUAL_BEAM' | 'CAST_BREAK' | 'VISUAL_SLASH' | 'KILL';

export interface GameEvent {
    type: GameEventType;
    pos: Point;
    value?: number; // Damage amount, heal amount, etc.
    text?: string; // For specialized text
    color?: string;
    skill?: Skill;
    sourceId?: string;
    targetId?: string;
    team?: Team;
}

export interface FloatingText {
    id: string;
    x: number;
    y: number;
    text: string;
    color: string;
    life: number;
    velocity: number;
}

// Tooling
export enum ToolType {
    SELECT = 'SELECT',
    ADD_BLUE = 'ADD_BLUE',
    ADD_RED = 'ADD_RED',
    OBSTACLE = 'OBSTACLE',
    DELETE = 'DELETE'
}

